#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { readdirSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(fileURLToPath(new URL('.', import.meta.url)), '..', '..');
const SKIP_DIRS = new Set(['node_modules', '.git']);

function discover(dir, out) {
  for (const entry of readdirSync(dir)) {
    if (SKIP_DIRS.has(entry)) continue;
    const full = join(dir, entry);
    const stat = statSync(full);
    if (stat.isDirectory()) {
      discover(full, out);
    } else if (entry.endsWith('.test.ts')) {
      out.push(full);
    }
  }
  return out;
}

function collectTargets(argPath) {
  if (!argPath) {
    return discover(join(repoRoot, '_local'), []);
  }
  const target = resolve(repoRoot, argPath);
  const stat = statSync(target);
  if (stat.isDirectory()) {
    return discover(target, []);
  }
  return [target];
}

const argPath = process.argv[2];
const files = collectTargets(argPath);

if (files.length === 0) {
  console.log('No *.test.ts files found.');
  process.exit(0);
}

const child = spawn(
  process.execPath,
  ['--test', '--test-reporter=spec', '--no-warnings=MODULE_TYPELESS_PACKAGE_JSON', ...files],
  { cwd: repoRoot, stdio: 'inherit' }
);

child.on('exit', (code) => {
  process.exit(code === null ? 1 : code);
});

